# prompts.py - picture prompts for coral-castle (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
HAT = " This character is a quiet stone builder: exactly the same simple white character, wearing only a small dark brown felt hat with a narrow brim (flat #704428 with a darker #3A2214 band, as measured on the hero) sitting on top of the round head - nothing else added, no hair, no clothes."
HARD = " This character is a construction worker: exactly the same simple white character, wearing only a round yellow hard hat (flat #FFD23F with a darker #E0AE1E shade and a short brim) sitting on top of the round head - nothing else added, no hair, no clothes."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border, no characters."
STONE = "pale porous limestone (flat #D9CDB4 with a darker #B3A587 shade and a few small darker pits #9C8E72)"
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
def tail(role, key='green'): return " Whole bodies in frame with a margin. " + CHAR + role + " " + KEY(key)

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, standing proud with both hands on the hips, chest out, a small confident closed-mouth smile, one eyebrow slightly raised. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + HAT + " " + KEY()),
 'ed3': ("3:2", ROW3 + "LEFT copy: side view facing to the RIGHT, pulling down hard on something above the head: both arms raised straight up above the head, both hands closed into empty fists one above the other, holding nothing, the body leaning back slightly, eyebrows down in effort, gritted teeth. MIDDLE copy: three-quarter view facing to the RIGHT, casually pushing something with just one finger: one arm stretched straight forward at shoulder height with only the index finger extended, the other hand resting on the hip, relaxed smug half-closed eyes, a small smile. RIGHT copy: facing the viewer, secretive: the index finger of one hand pressed against the closed mouth in a 'shh' gesture, eyes looking sideways to the left suspiciously, eyebrows lowered." + tail(HAT)),
 'crew3': ("3:2", ROW3 + "LEFT copy: side view facing to the RIGHT, pushing hard against something heavy: both arms stretched straight forward at shoulder height with open palms facing forward, the body leaning far forward, one leg bent forward and one leg stretched back, eyes squeezed shut, gritted teeth. MIDDLE copy: side view facing to the LEFT, pulling hard backwards: both hands held together in front of the chest as closed empty fists, holding nothing, the body leaning far back, legs braced forward, eyebrows down, mouth wide open straining with the pink tongue showing. RIGHT copy: facing the viewer, exhausted and puzzled: one hand scratching the side of the hard hat, the other arm hanging down, eyebrows tilted up in the middle, a small wavy mouth." + tail(HARD)),
 'stones': ("3:2", f"Three separate stone objects side by side in one row with wide empty gaps between them, all drawn the same scale, bold clean thick outlines, all made of the same {STONE}. LEFT: one big rough square-ish block of stone with slightly uneven sides, about as wide as it is tall. MIDDLE: a tall thick upright rectangular stone slab like a heavy door, about twice as tall as it is wide, straight sides, rough surface, seen straight from the front. RIGHT: a tall slim stone obelisk with a pointed top. No faces, no carvings, no text. " + OBJ + " " + KEY()),
 'wall': ("3:2", f"A long castle wall built of big rough blocks of {STONE}, seen straight from the front: one row of tall upright stone blocks with a flat top, the wall about three times as wide as it is tall, with one square stone tower twice as tall as the wall at the LEFT end with a few square notches on its top. In the middle of the wall there is one empty rectangular doorway gap about as wide as one block, open from the bottom of the wall to the top of the wall, the flat green background shows through the gap. No gate, no door, no plants, no people, no text. " + OBJ + " " + KEY()),
 'crane': ("3:2", "Side view of one chunky yellow cartoon mobile crane truck facing to the LEFT: a short truck body on four big black wheels with grey hubs, a small square driver cab with one window at the LEFT front end, one long straight yellow boom (#FFC72C with a darker #E0A21A shade) rising diagonally up to the upper LEFT from the back of the truck, a thin black cable hanging straight down from the tip of the boom with a red hook block at its end. Friendly simple shapes, chunky proportions, no markings, no logos, no text. The whole crane in frame with a margin. " + OBJ + " " + KEY('magenta')),
 'yard': ("2:3", "A wide flat backyard in Florida seen from the side at ground level, vertical picture. The top 55 % is a plain pale-blue sky with two small flat white clouds. The horizon line is flat at 55 % of the height: on it, a few low rounded dark-green bushes in the distance and two tall slim palm trees with gently curved trunks, one near the LEFT edge and one near the RIGHT edge. Below the horizon, flat ground of short green grass (#8CC152 with a lighter #A8D46B band near the horizon) with a few small pale flat stones. Clean open ground in the middle where buildings and characters will stand. No buildings, no walls, no people, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# coral-castle - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
